import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const iceMagicScenarios=['ice-arrow-ordinary','ice-arrow-dedicated','ice-stream-ordinary','ice-stream-dedicated','ice-stream-declined','ice-stream-relative'] as const;
export type IceMagicScenario=typeof iceMagicScenarios[number];
export function isIceMagicScenario(name:string):name is IceMagicScenario{return (iceMagicScenarios as readonly string[]).includes(name);}
export function iceMagicMode(name:IceMagicScenario){const arrow=name.startsWith('ice-arrow'),dedicated=!name.endsWith('ordinary');return {card:arrow?'a2-p12-r2c2':'a2-p12-r2c3',name:arrow?'氷矢':'凍流',dedicated,arrow,use:arrow?4:5,effect:(arrow?4:5)+(dedicated?2:0),damage:dedicated?6:4,maai:arrow?1:2,ignore:name!=='ice-stream-declined',relative:name==='ice-stream-relative'};}
export function makeIceMagicScenario(name:IceMagicScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;defender?:string;guard?:'none'|'soldier'|'water'|'water-blessed';silenced?:boolean}={}){
 const m=iceMagicMode(name),guardMode=options.guard??(m.arrow?'soldier':m.relative?'water-blessed':'water');let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??'凍気のアイエル');assignCharacter(s,b,options.defender??(options.silenced?'大神官ジル':'黒騎士ガーウィン'));assignCharacter(s,c,options.silenced?'侍大将のシン':'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const stats=gameStats(s,a);s.players[a]!.permanent!.magic_level=20+(options.level??m.use)-stats.magic_level;s.players[a]!.permanent!.spirit=20+6-stats.spirit;
 const card=takeCard(s,a,m.card),prayer=takeCard(s,a,'必勝の祈り'),maai=takeCard(s,b,'a2-p07-r1c1'),maai2=takeCard(s,b,'a2-p07-r1c2'),evade=takeCard(s,b,'a2-p05-r3c1'),fate=takeCard(s,c,'命運凶変'),guard=guardMode==='none'?null:takeCard(s,b,guardMode==='soldier'?'兵士':'水竜'),rear=!m.arrow&&(guardMode==='water'||guardMode==='water-blessed')?takeCard(s,c,'兵士'):null,silence=options.silenced?takeCard(s,b,'沈黙'):null;let blessing:string|null=null;if(guardMode==='water-blessed'){blessing=takeCard(s,b,'祝福');s.players[b]!.hand=s.players[b]!.hand.filter(id=>id!==blessing);s.deck.unshift(blessing);}for(const id of [a,b,c,d])trimHand(s,id,card,prayer,maai,maai2,evade,fate,...(guard?[guard]:[]),...(rear?[rear]:[]),...(silence?[silence]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];if(blessing)s.deck=[blessing,...s.deck.filter(id=>id!==blessing)];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(options.silenced?6:1)},r=transition(s,input,e);if(!r.ok)throw Error(`ICE_MAGIC_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('ICE_MAGIC_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('ICE_MAGIC_IDS');}
 function advanceTo(target:string){for(let n=0;n<200;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===target)return;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>x!==card).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('ICE_MAGIC_TURN');}throw Error('ICE_MAGIC_TURN_LIMIT');}
 for(const id of [a,b,c,d]){if(guard&&id===b)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});if(rear&&id===c)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:rear});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(blessing){act(a,{type:'PASS_ACTION'});advanceTo(a);if(!s.players[b]!.open.includes(blessing))throw Error('ICE_BLESSING_DRAW');}if(silence){act(a,{type:'PASS_ACTION'});advanceTo(b);act(b,{type:'ATTACK',cardInstanceId:silence,targetIds:[a],dedicated:false});advanceTo(a);if(!s.discard.includes(silence))throw Error('ICE_MAGIC_SILENCE_PAYMENT');}return s;
}
